<?php if ($filters['opcion'] == 1){ ?>
  <script>
    function selectMarcados(form1)
    {
      var username="";
      var id="";
      var selected = [];
      jQuery('.check_').each(function() {
        if (jQuery(this).is(":checked")) {
          var id = jQuery(this).attr('value');
          var nomb = jQuery("#"+jQuery(this).attr('name').replace('marca', 'nomb')).val();
          var causid = jQuery("#"+jQuery(this).attr('name').replace('marca', 'cargo')).val();
          var cargo_text = jQuery("#"+jQuery(this).attr('name').replace('marca', 'cargo_text')).val();
          var avatar = jQuery("#"+jQuery(this).attr('name').replace('marca', 'avatar')).val();
          var preload_data = {id: id, text: nomb + ' - ' + cargo_text, cid: causid, img: avatar};
          selected.push(preload_data);    
        }
      });
      //************************************************************************
      updateJSON(selected);
      parent.jQuery.CloseModalSIMAD();
    }

    function updateJSON(json){
        var responses = json;
        if(responses != null){
        var xselect2 = parent.jQuery("#<?php echo $filters['campoText']; ?>").data('select2');
        if(xselect2 != null){
          var oldjson = parent.jQuery("#<?php echo $filters['campoText']; ?>").select2('data');
        }
        //********************************************************************
        var text_name = parent.jQuery("#<?php echo $filters['campoText']; ?>").val().split(",");
            var idold = parent.jQuery("#<?php echo $filters['campoId']; ?>").val().split(",");
            var cidold = parent.jQuery("#<?php echo $filters['cargoId']; ?>").val().split(",");
            idold = jQuery.grep(idold, function(n){ return (n); });
            cidold = jQuery.grep(cidold, function(n){ return (n); });
        text_name = jQuery.grep(text_name, function(n){ return (n); });
            //avatar = jQuery.grep(avatar, function(n){ return (n); });
            //********************************************************************
            jQuery.each(json, function() {
                idold.push(this.id);
                cidold.push(this.cid);
                text_name.push(this.text);
            });
        //********************************************************************
        //idold = jQuery.unique( idold );
        //cidold = jQuery.unique( cidold );
            //********************************************************************
            parent.jQuery("#<?php echo $filters['campoId']; ?>").val(idold.join(","));
            parent.jQuery("#<?php echo $filters['cargoId']; ?>").val(cidold.join(","));
            //********************************************************************
        if(xselect2 != null){
          var data_selected = oldjson.concat(json);
          parent.jQuery("#<?php echo $filters['campoText']; ?>").select2('data', data_selected).trigger("change");
        }else{
          parent.jQuery("#<?php echo $filters['campoText']; ?>").val(text_name.join(","));
        }        
        }
    }

    jQuery("#selectall").click(function(){
        jQuery.ajax({
            type: "POST",
            url: "selectAllUser?a=1<?php echo ($query_filter); ?>",        
            success: function(request,data){
                //console.log(request);
                updateJSON(request);
          javascript:parent.jQuery.CloseModalSIMAD();
            },
            error: function(){
                alert("failure");
            }
        });
    });
  </script>
